pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;

    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(address caller, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        vm.assume(_feeRate <= 5000);

        vm.prank(caller);
        bool ok1;
        try c.initialize(address(0), _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        vm.prank(caller);
        bool ok2;
        try c.initialize(address(0), _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(!ok1 || !ok2);
    }
}
